app.MapPost("/chat/stream", async (ChatRequest req, IChatClient chat,
                                   HttpContext ctx, CancellationToken ct) =>
{
    ctx.Response.ContentType = "text/event-stream";
    await foreach (var update in chat.GetStreamingResponseAsync(req.Messages, cancellationToken: ct))
    {
        var json = JsonSerializer.Serialize(new { text = update.Text });
        await ctx.Response.WriteAsync($"data: {json}\n\n", ct);
        await ctx.Response.Body.FlushAsync(ct);
    }
});

answer = signal('');
private ctrl?: AbortController;

async ask(question: string) {
  this.ctrl = new AbortController();
  const res = await fetch('/api/chat/stream', { method: 'POST', signal: this.ctrl.signal,
    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question }) });
  const reader = res.body!.pipeThrough(new TextDecoderStream()).getReader();
  let buf = '';
  for (let r = await reader.read(); !r.done; r = await reader.read()) {
    buf += r.value;
    const events = buf.split('\n\n'); buf = events.pop()!;
    for (const e of events) if (e.startsWith('data: '))
      this.answer.update(a => a + JSON.parse(e.slice(6)).text);
  }
}
stop() { this.ctrl?.abort(); }
